// BR Medic — scheduled weekly anti-pattern scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function runBrmWeeklyScan() {
    try {
        var scanner = new BrmScanner();
        var scanId = scanner.runDeltaScan();
        gs.info('BR Medic weekly scan complete: scan_id=' + scanId);
    } catch (e) {
        gs.error('BR Medic weekly scan failed: ' + e.message);
    }
})();
